# Debounced Search Input

Here are the main approaches:

## React (useEffect + cleanup)

```javascript
import { useState, useEffect } from 'react';

function SearchUsers() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!query) {
      setResults([]);
      return;
    }

    const timer = setTimeout(() => {
      setLoading(true);
      fetch(`/api/search?q=${encodeURIComponent(query)}`)
        .then(res => res.json())
        .then(data => setResults(data))
        .finally(() => setLoading(false));
    }, 300); // 300ms delay

    return () => clearTimeout(timer); // cleanup
  }, [query]);

  return (
    <div>
      <input
        type="text"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search..."
      />
      {loading && <p>Loading...</p>}
      <ul>
        {results.map(item => <li key={item.id}>{item.name}</li>)}
      </ul>
    </div>
  );
}
```

## Plain JavaScript

```javascript
function createDebounce(fn, delay) {
  let timeoutId;
  return function (...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn(...args), delay);
  };
}

const searchInput = document.querySelector('#search');
const resultsList = document.querySelector('#results');

const debouncedSearch = createDebounce((query) => {
  fetch(`/api/search?q=${encodeURIComponent(query)}`)
    .then(res => res.json())
    .then(data => {
      resultsList.innerHTML = data.map(item => `<li>${item.name}</li>`).join('');
    });
}, 300);

searchInput.addEventListener('input', (e) => {
  debouncedSearch(e.target.value);
});
```

## With Lodash

```javascript
import { debounce } from 'lodash';

const debouncedFetch = debounce((query) => {
  fetch(`/api/search?q=${encodeURIComponent(query)}`)
    .then(res => res.json())
    .then(data => console.log(data));
}, 300);

searchInput.addEventListener('input', (e) => {
  debouncedFetch(e.target.value);
});
```

**Key points:**
- **300ms** is typical; adjust based on your API speed
- **useEffect cleanup** prevents stale requests
- **Trailing debounce** (default) fires after delay ends — best for search

Pick React example if using React, plain JS for vanilla, Lodash if already using it.
